/** Public entry point — the only module consumers/docs should import from. */
export { useDataGridPinnedRows, type UseDataGridPinnedRowsOptions, type UseDataGridPinnedRowsResult } from "./use-data-grid-pinned-rows";
export { DataGridPinnedRow, type DataGridPinnedRowProps } from "./pinned-row";
export { DataGridPinnedRowBand, type DataGridPinnedRowBandProps } from "./pinned-row-band";
export {
  useDataGridAggregate,
  DataGridAggregateReporter,
  type AggregateReducer,
  type AggregateSpecs,
  type UseDataGridAggregateOptions,
  type DataGridAggregateReporterProps,
} from "./use-data-grid-aggregate";

"use client";

import { useMemo } from "react";
import type { RowBandRenderCtx, RowBandsSpec } from "@/registry/default/components/data-grid/data-grid";
import { DataGridPinnedRowBand } from "./pinned-row-band";

/** Options for {@link useDataGridPinnedRows}. */
export type UseDataGridPinnedRowsOptions = {
  /** Rows pinned in a sticky band directly under the header (e.g. a computed totals row) — a SEPARATE array from `data`, not indices into it. Omit (or pass `[]`) for no top band. */
  topRows?: readonly unknown[];
  /** Rows pinned in a sticky band at the viewport's bottom edge; see {@link UseDataGridPinnedRowsOptions.topRows}. */
  bottomRows?: readonly unknown[];
};

/** Return value of {@link useDataGridPinnedRows}. */
export type UseDataGridPinnedRowsResult = {
  /** Pass this into `<DataGridProvider rowBands={rowBands}>` (or `<DataGrid rowBands={rowBands}>`) — stable identity across renders as long as `topRows`/`bottomRows` keep the same array references. */
  rowBands: RowBandsSpec;
};

const EMPTY_ROWS: readonly never[] = [];

/**
 * Pinned top/bottom row bands, as a single hook. Unlike `data-grid-presence`/`data-grid-fill`
 * (which register into the generic `overlayPlugins` paint seam), row bands affect layout height
 * and `aria-rowcount`, so core needs `topRows`/`bottomRows.length` SYNCHRONOUSLY at first render —
 * root.tsx keeps all of that arithmetic and calls this spec's `renderBand` (see `RowBandsSpec`'s
 * doc comment in `layout-context.ts`). Cells render via the same `DataGridCell`/cell-type pipeline
 * as data rows (same columns, alignment, formatting) but are readOnly by default unless a column's
 * own `readOnly` says otherwise, and aren't keyboard-navigable in v1 (documented).
 */
export function useDataGridPinnedRows(options: UseDataGridPinnedRowsOptions = {}): UseDataGridPinnedRowsResult {
  const { topRows = EMPTY_ROWS, bottomRows = EMPTY_ROWS } = options;
  // Stable identity keyed on the two row arrays' own references — same guardrail contract as
  // overlayPlugins (root.tsx's dev-mode warning fires if this churns every render for no reason).
  const rowBands = useMemo<RowBandsSpec>(
    () => ({
      topRows,
      bottomRows,
      renderBand: renderPinnedRowBand,
    }),
    [topRows, bottomRows],
  );

  return { rowBands };
}

function renderPinnedRowBand(ctx: RowBandRenderCtx) {
  const { position, rows, windowedColumns, layout, rowHeight, template, headerHeight, ariaRowIndexBase } = ctx;
  return (
    <DataGridPinnedRowBand
      position={position}
      rows={rows}
      windowedColumns={windowedColumns}
      layout={layout}
      rowHeight={rowHeight}
      template={template}
      headerHeight={headerHeight}
      ariaRowIndexBase={ariaRowIndexBase}
    />
  );
}

"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { DataGridCell, useDataGridSelector, type DataGridStoreState } from "@/registry/default/components/data-grid/data-grid";
import type { GridColumnLayout, WindowedColumn } from "@/registry/default/components/data-grid/data-grid-sdk";

export type DataGridPinnedRowProps = {
  /** The band this row belongs to; part of the fallback row id. */
  position: "top" | "bottom";
  /** The consumer-supplied pinned row object (from `useDataGridPinnedRows`'s `topRows`/`bottomRows` options — never a member of `data`). */
  row: unknown;
  /** Position within its own band, 0-based — the `data-grid-pinned-row-index` marker and the `getRowId` index argument of the row's resolved id; never `ViewCoord`/`aria-colindex` (pinned rows aren't in the data index space). */
  bandIndex: number;
  windowedColumns: readonly WindowedColumn[];
  layout: GridColumnLayout;
  gridRowStart: number;
  /** Root's aria index layout: header=1, pinned-top next, then data rows, pinned-bottom last. */
  ariaRowIndex: number;
  className?: string;
};

function resolvePinnedRowId(getRowId: DataGridStoreState["getRowId"], row: unknown, bandIndex: number, position: "top" | "bottom"): string {
  let id: unknown;
  try {
    id = getRowId(row, bandIndex);
  } catch {
    id = undefined;
  }
  return typeof id === "string" && id !== "" ? id : `__pinned-${position}-${bandIndex}`;
}

/**
 * A pinned top/bottom band row: reuses
  * `DataGridCell` in its `pinnedRow` mode for identical cell-type rendering/alignment/column tracks as
 * data rows, but bypasses `DataGridRow`'s `useDataGridRow(viewRowIndex)` store lookup entirely —
 * pinned rows are a separate array the consumer supplies to `useDataGridPinnedRows`, not indices
 * into `data`/`viewIndex`, so they never sort, filter, or participate in range selection or the
 * rows-channel (documented v1 scope). Not memoized like `DataGridRow`: pinned bands are always
 * fully rendered (never windowed/virtualized — a handful of totals/frozen rows, not tens of
 * thousands), so there's no window-shift-driven re-render pressure to protect against.
 */
export function DataGridPinnedRow(props: DataGridPinnedRowProps): ReactNode {
  const { position, row, bandIndex, windowedColumns, layout, gridRowStart, ariaRowIndex, className } = props;
  const getRowId = useDataGridSelector((s) => s.getRowId);
  // Pinned rows such as aggregates often carry no id, so a throwing or empty getRowId falls back to a band id.
  const rowId = resolvePinnedRowId(getRowId, row, bandIndex, position);
  const markerColOffset = layout.markerWidth > 0 ? 2 : 1;
  return (
    <div
      role="row"
      aria-rowindex={ariaRowIndex}
      data-grid-pinned-row-index={bandIndex}
      className={cn("group/row", className)}
      style={{
        display: "grid",
        gridTemplateColumns: "subgrid",
        gridColumn: "1 / -1",
        gridRowStart,
      }}
    >
      {windowedColumns.map(({ column, index }) => (
        <DataGridCell
          key={column.id}
          row={row}
          rowId={rowId}
          rowIndex={bandIndex}
          column={column}
          columnIndex={index}
          gridColOffset={markerColOffset}
          pinnedRow
        />
      ))}
    </div>
  );
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { GRID_LAYER, type GridColumnLayout, type WindowedColumn } from "@/registry/default/components/data-grid/data-grid-sdk";
import { DataGridPinnedRow } from "./pinned-row";

/** Props for {@link DataGridPinnedRowBand}. */
export type DataGridPinnedRowBandProps = {
  position: "top" | "bottom";
  rows: readonly unknown[];
  windowedColumns: readonly WindowedColumn[];
  layout: GridColumnLayout;
  rowHeight: number;
  template: string;
  /** The sticky header track's own height (not including this or any pinned band) — where the top band's `insetBlockStart` lands, directly under the header. */
  headerHeight: number;
  /**
   * `aria-rowindex` base for this band's rows (root's aria index layout: header=1, pinned-top
   * next, then data rows, pinned-bottom last). Top band: 2 (right after the header). Bottom band:
   * `2 + pinnedTopCount + dataRowCount` (right after every data row) — root computes both bases and
   * passes them through `RowBandRenderCtx`.
   */
  ariaRowIndexBase: number;
};

/**
 * A pinned-row sticky band: same layering as core's header layer — absolutely positioned inside
 * the sticky Viewport, counter-translated horizontally by the live scroll var so its cells track
 * the column canvas 1:1, but never moves vertically (rows canvas is the only vertically-scrolling
 * layer). The top band sits directly under the header; the bottom band sits flush with the
 * viewport's bottom edge (`insetBlockEnd: 0`) — both stay "in place" while data rows scroll
 * underneath, which is what core's frozen-edge shadow (root.tsx) keys off of.
 * `useDataGridPinnedRows`'s `rowBands.renderBand` calls this once per non-empty band.
 */
export function DataGridPinnedRowBand(props: DataGridPinnedRowBandProps): ReactNode {
  const { position, rows, windowedColumns, layout, rowHeight, template, headerHeight, ariaRowIndexBase } = props;
  if (rows.length === 0) return null;

  const bandHeight = rows.length * rowHeight;
  const layerStyle: CSSProperties = {
    position: "absolute",
    insetInlineStart: 0,
    display: "grid",
    gridTemplateColumns: template,
    gridAutoRows: `${rowHeight}px`,
    height: bandHeight,
    // stacking context, same reasoning as header.tsx's own zIndex comment — must paint above the
    // rows canvas in DOM order regardless of scroll-driven transforms; below the header (zIndex 4).
    zIndex: GRID_LAYER.pinnedRowBand,
    // --grid-dir (-1 LTR, 1 RTL) signs the horizontal term, same as core's header/canvas layers:
    // the grid tracks mirror themselves under dir=rtl but transforms stay physical.
    transform: "translate3d(calc(var(--grid-dir, -1) * var(--grid-scroll-left, 0px)), 0, 0)",
    ...(position === "top" ? { insetBlockStart: headerHeight } : { insetBlockEnd: 0 }),
  };

  return (
    <div role="rowgroup" data-grid-pinned-row-band={position} style={layerStyle}>
      {rows.map((row, i) => (
        <DataGridPinnedRow
          // oxlint-disable-next-line react/no-array-index-key -- a pinned row id can be a band id; band position is a stable key for a small consumer array.
          key={i}
          position={position}
          row={row}
          bandIndex={i}
          windowedColumns={windowedColumns}
          layout={layout}
          gridRowStart={i + 1}
          ariaRowIndex={ariaRowIndexBase + i}
          className={position === "bottom" ? "border-t border-border" : undefined}
        />
      ))}
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef, type ReactNode } from "react";
import { useStore } from "zustand";
import { getCellValue, type AnyColumnDef, type DataGridStoreState } from "@/registry/default/components/data-grid/data-grid";
import { isDev, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Built-in reducers; a function receives every resolved value plus its source rows (empty values included — unlike the built-ins, a custom reducer owns its own empty handling). `TData` is the grid's row type: pass it at the hook call (or annotate `specs` as `AggregateSpecs<Row>`) so `rows` is typed. */
export type AggregateReducer<TData = unknown> = "sum" | "avg" | "min" | "max" | "count" | ((values: readonly unknown[], rows: readonly TData[]) => unknown);

/** One reducer per column id to aggregate. */
export type AggregateSpecs<TData = unknown> = Record<string, AggregateReducer<TData>>;

/** Options for {@link useDataGridAggregate}. */
export type UseDataGridAggregateOptions = {
  /** `"view"` (default) reduces over the sorted/filtered `viewIndex` — the rows actually visible. `"all"` reduces over the full `data` array, ignoring any active filter. */
  scope?: "view" | "all";
};

const NUMERIC_REDUCERS = new Set(["sum", "avg", "min", "max"]);

function reduceNumeric(reducer: "sum" | "avg" | "min" | "max", values: readonly number[]): number | undefined {
  if (values.length === 0) return undefined;
  switch (reducer) {
    case "sum":
      return values.reduce((a, b) => a + b, 0);
    case "avg":
      return values.reduce((a, b) => a + b, 0) / values.length;
    case "min":
      return values.reduce((a, b) => Math.min(a, b));
    case "max":
      return values.reduce((a, b) => Math.max(a, b));
  }
}

function aggregateColumn<TData>(reducer: AggregateReducer<TData>, column: AnyColumnDef, rows: readonly unknown[]): unknown {
  const values = rows.map((row) => getCellValue(row, column));
  // Boundary cast: the store keeps rows as unknown[], the user's reducer gets them typed.
  if (typeof reducer === "function") return reducer(values, rows as readonly TData[]);

  const nonEmpty = values.filter((v) => v !== null && v !== undefined);
  if (reducer === "count") return nonEmpty.length;
  if (NUMERIC_REDUCERS.has(reducer)) return reduceNumeric(reducer, nonEmpty as number[]);
  return undefined;
}

// Fires at most once per app, dev-only: a sparse (lazy) data array reached the reducer.
let warnedSparseData = false;

function warnSparseData(scope: "view" | "all", holes: number): void {
  if (!isDev() || warnedSparseData) return;
  warnedSparseData = true;
  console.warn(
    `[data-grid-pinned-rows] useDataGridAggregate (scope "${scope}") skipped ${holes} unloaded row(s): the data array is sparse (lazy loading), so the result covers loaded rows only. Use server-side totals or compute them outside the grid.`,
  );
}

// Fires at most once per app, dev-only: a spec key that matches no column id.
let warnedUnknownSpecKey = false;

function warnUnknownSpecKey(columnId: string): void {
  if (!isDev() || warnedUnknownSpecKey) return;
  warnedUnknownSpecKey = true;
  console.warn(
    `[data-grid-pinned-rows] useDataGridAggregate: spec key "${columnId}" matches no column id and is ignored (check for a typo)`,
  );
}

function computeAggregate<TData>(state: DataGridStoreState, specs: AggregateSpecs<TData>, scope: "view" | "all"): Record<string, unknown> {
  const byId = new Map(state.columns.map((c) => [c.id, c] as const));
  const scoped = scope === "all" ? state.data : state.viewIndex.map((i) => state.data[i]);
  // undefined rows are unloaded holes of a lazy grid; reduce over the loaded rows only.
  const rows = scoped.filter((row) => row !== undefined);
  if (rows.length !== scoped.length) warnSparseData(scope, scoped.length - rows.length);
  const result: Record<string, unknown> = {};
  for (const [columnId, reducer] of Object.entries(specs)) {
    const column = byId.get(columnId);
    if (!column) {
      warnUnknownSpecKey(columnId);
      continue;
    }
    result[columnId] = aggregateColumn(reducer, column, rows);
  }
  return result;
}

/**
 * Filter-aware aggregation for pinned totals/summary rows: reduces `specs` over the
 * grid's own state and returns a plain `{ [columnId]: value }` object — the same shape
 * `useDataGridPinnedRows`'s `topRows`/`bottomRows` expect, since pinned cells resolve values through
 * each column's `accessorKey`/`accessorFn` exactly like data rows. The object carries no row id, so
 * a pinned band gives it a band id when `getRowId` cannot resolve one. Values are resolved through
 * `getCellValue`, so `accessorFn` columns aggregate correctly, not just plain fields. Defaults to
 * reducing over `viewIndex` (sorted/filtered display order) — pass `scope: "all"` to reduce
 * over the raw `data` instead, ignoring the active filter. Recomputes only when `viewIndex`, `data`,
 * `scope`, or the `specs` object's own identity changes, so scrolling (no store write touches any of
 * those) never recomputes — same identity-guardrailed contract as `rowBands`/`overlayPlugins`; define
 * `specs` at module scope or memoize it, same discipline as any other grid callback prop.
 * `undefined` rows (unloaded holes of a lazy grid) are skipped and a dev warning fires once — on a
 * lazy grid the result covers loaded rows only. A spec key that matches no column id is ignored
 * and a dev warning fires once. `TData` types `rows` in custom reducers (see {@link AggregateReducer}).
 */
export function useDataGridAggregate<TData = unknown>(specs: AggregateSpecs<TData>, options: UseDataGridAggregateOptions = {}): Record<string, unknown> {
  const { scope = "view" } = options;
  const storeApi = useDataGridStoreApi();
  const cache = useRef<{ viewIndex: number[]; data: readonly unknown[]; scope: string; specs: AggregateSpecs<TData>; result: Record<string, unknown> } | null>(null);

  return useStore(storeApi, (state) => {
    const c = cache.current;
    if (c && c.viewIndex === state.viewIndex && c.data === state.data && c.scope === scope && c.specs === specs) {
      return c.result;
    }
    const result = computeAggregate(state, specs, scope);
    cache.current = { viewIndex: state.viewIndex, data: state.data, scope, specs, result };
    return result;
  });
}

/** Props for {@link DataGridAggregateReporter}. */
export type DataGridAggregateReporterProps<TData = unknown> = {
  specs: AggregateSpecs<TData>;
  options?: UseDataGridAggregateOptions;
  /** Called with the aggregated row whenever it changes — feed it into a `useState` that becomes a pinned band's `topRows`/`bottomRows` entry. */
  onChange: (row: Record<string, unknown>) => void;
};

/**
 * Bridges {@link useDataGridAggregate} out of the store. `rowBands` is a `DataGridProvider` prop —
 * evaluated in the PARENT before the store exists — so a component that needs the live, filter-aware
 * aggregate to feed back into it must sit INSIDE the provider and report out. Render this as a plain
 * child anywhere under `<DataGridProvider>` (e.g. next to `<DataGridRoot>`) and hold its `onChange`
 * result in the parent's own state; that state is what you pass into `useDataGridPinnedRows`'s
 * `topRows`/`bottomRows`. A layout effect (not a passive one) reports the result before the browser paints,
 * so the parent's second render lands in the same frame as the first — no flash of an empty band.
 * Renders nothing.
 */
export function DataGridAggregateReporter<TData = unknown>(props: DataGridAggregateReporterProps<TData>): ReactNode {
  const { specs, options, onChange } = props;
  const row = useDataGridAggregate(specs, options);
  // Hold the latest callback in a ref and key the effect on `row` alone: an inline `onChange`
  // (fresh identity every parent render) would otherwise re-fire the effect on every render, and
  // a parent that stores the row with a spread (`{ ...prev, ...row }`) loops that forever.
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  useLayoutEffect(() => {
    onChangeRef.current(row);
  }, [row]);
  return null;
}
